import {client,safeURL,escapeHTML as e} from './cms-data.js';
export const contentFields=[
 ['identity','Name','.identity strong','text','Hero & navigation'],['role','Professional title','.identity small','text','Hero & navigation'],['heroTitle','Main headline','.intro h1','textarea','Hero & navigation'],['heroDescription','Introduction text','.intro > p','textarea','Hero & navigation'],['brand','Navigation name','.brand','text','Hero & navigation'],['navAbout','About link label','.nav-side:first-child a:first-child','text','Hero & navigation'],['navProjects','Projects link label','.nav-side:first-child a:nth-child(2)','text','Hero & navigation'],['navWork','Work link label','.nav-side:last-child a:first-child','text','Hero & navigation'],['navContact','Contact link label','.nav-side:last-child a:nth-child(2)','text','Hero & navigation'],['resumeLabel','Resume button text','.hero-actions > a','text','Hero & navigation'],['resumeUrl','Resume link','.hero-actions > a','url','Hero & navigation'],['availability','Availability text','.pill-outline','text','Hero & navigation'],['avatar','Profile image','.avatar','image','Hero & navigation'],['avatarAlt','Profile image description','.avatar','alt','Hero & navigation'],
 ['projectsHeading','Projects heading','#projects-heading','text','Projects & showreel'],['showreelTitle','Showreel title','.motion-project h3','text','Projects & showreel'],['showreelUrl','Showreel video URL','.motion-project source','video','Projects & showreel'],['showreelPoster','Showreel cover image','.motion-project video','poster','Projects & showreel'],
 ['aboutHeading','About heading','#about-heading','text','About & skills'],['aboutLead','About introduction','.about-lead','textarea','About & skills'],['toolkitHeading','Toolkit heading','.stack-heading','text','About & skills'],['toolkitDescription','Toolkit description','.stack-description','textarea','About & skills'],['aboutStory','About story','.about-story','textarea','About & skills'],
 ['contactHeading','Contact heading','.contact h2','textarea','Contact & footer'],['contactLabel','Email button text','.contact-button','text','Contact & footer'],['email','Contact email','.contact-button','email','Contact & footer'],['copyright','Copyright text','.footer-line span:first-child','text','Contact & footer'],['credit','Footer credit','.footer-line span:last-child','text','Contact & footer'],['pageTitle','Browser page title','title','text','Page settings'],['metaDescription','Search description','meta[name=description]','meta','Page settings']
];
export const contentLists=[['services','Areas of work / services','.tags:not(.stack-tags)','tags'],['skills','Tools & technologies','.stack-tags','tags'],['heroImages','Hero image carousel','.work-ribbon','images'],['aboutImages','About image carousel','.about-ribbon','images'],['socials','Social links','.footer-links','links']];
export async function websiteContent(){const db=await client();if(db){const {data,error}=await db.from('portfolio_site_content').select('*').eq('id','main').single();if(error)throw error;return data;}return {id:'main',revision:0,content:await fetch('/site-content.json').then(r=>r.json())};}
export function applyContent(content,doc=document){
 for(const [key,,selector,kind] of contentFields){if(!(key in content))continue;const el=doc.querySelector(selector);if(!el)continue;const value=String(content[key]??'');
 if(['url','image','poster','video'].includes(kind)){const url=value?safeURL(value,true):'';if(kind!=='poster')el.hidden=!url;if(kind==='url')el.setAttribute('href',url);else if(kind==='image')el.setAttribute('src',url);else if(kind==='poster')el.setAttribute('poster',url);else{const video=el.closest('video');if(video.querySelector('source').getAttribute('src')!==url){el.setAttribute('src',url);video.load?.();}video.closest('.motion-project').hidden=!url;}}
 else if(kind==='email'){const valid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);el.setAttribute('href',valid?'mailto:'+value:'');el.hidden=!valid;}
 else if(kind==='alt')el.setAttribute('alt',value);else if(kind==='meta')el.setAttribute('content',value);else{el.textContent=value;el.hidden=!value.trim();}
 }
 for(const [key,,selector,kind] of contentLists){if(!Array.isArray(content[key]))continue;const el=doc.querySelector(selector);if(!el)continue;el.hidden=!content[key].length;
 if(kind==='tags')el.innerHTML=content[key].map(t=>`<span class="tag">${e(t)}</span>`).join('');
 else if(kind==='links')el.innerHTML=content[key].filter(l=>safeURL(l.url)).map(l=>`<a href="${e(safeURL(l.url))}" target="_blank" rel="noopener noreferrer">${e(l.label)}</a>`).join('<span aria-hidden="true">·</span>');
 else{const group=el.querySelector('.ribbon-group,.about-group');group.innerHTML=content[key].filter(i=>safeURL(i.url,true)).map(i=>`<div class="${key==='heroImages'?'ribbon-tile':'about-tile'}"><img src="${e(safeURL(i.url,true))}" alt="${e(i.alt)}" loading="lazy" decoding="async"></div>`).join('');const track=group.parentElement;[...track.children].slice(1).forEach(n=>n.remove());if(group.children.length){const copy=group.cloneNode(true);copy.setAttribute('aria-hidden','true');track.append(copy);}el.scrollLeft=0;}
 }
 for(const selector of ['.hero-actions > a','.contact-button']){const el=doc.querySelector(selector);if(!el.textContent.trim())el.hidden=true;else el.setAttribute('aria-label',el.textContent+(el.target==='_blank'?' (opens in a new tab)':''));}
 for(const [key,selector] of [['showAbout','#about'],['showProjects','#projects'],['showContact','#contact']])if(typeof content[key]==='boolean')doc.querySelector(selector).hidden=!content[key];
}
